const char *CrystalStdVersion() { return "1.19.1"; }

const CrystalStdType *CrystalStdTypes(size_t *count) {
  *count = sizeof(kTypes) / sizeof(kTypes[0]);
  return kTypes;
}

const CrystalStdMethod *CrystalStdMethods(size_t *count) {
  *count = sizeof(kMethods) / sizeof(kMethods[0]);
  return kMethods;
}

const CrystalStdConst *CrystalStdConsts(size_t *count) {
  *count = sizeof(kConsts) / sizeof(kConsts[0]);
  return kConsts;
}
